-- WorldDB: registry for the compiled world data (phase 19, docs/DYNAMIC_GUIDE_PLAN.md s4.1).
-- The files under World/ are generated by `python -m pipeline compile-world` and register here.
-- A zone file registers a builder function; the zone's tables are only created the first time
-- the zone is asked for, so loading the add-on stays cheap. Nothing in the legacy engine reads
-- this yet: the reconciler and planner (phases 20 and 21) are its first users.
local _, K = ...

local DB = {
    index = nil,   -- Index.lua: where each quest, NPC and object lives, zone levels, groups
    travel = nil,  -- Travel.lua: flight nodes, docks, adjacency, rough costs
    builders = {}, -- uiMapID -> function returning the zone table (dropped once built)
    zones = {},    -- uiMapID -> built zone table
}
K.WorldDB = DB

function DB.RegisterIndex(index)
    DB.index = index
end

function DB.RegisterTravel(travel)
    DB.travel = travel
end

function DB.RegisterZone(uiMap, builder)
    DB.builders[uiMap] = builder
    DB.zones[uiMap] = nil
end

-- Returns the zone table for a uiMapID (0 is the "outside" bucket), building it on first use.
function DB.Zone(uiMap)
    local zone = DB.zones[uiMap]
    if zone then
        return zone
    end
    local builder = DB.builders[uiMap]
    if not builder then
        return nil
    end
    zone = builder()
    DB.zones[uiMap] = zone
    DB.builders[uiMap] = nil
    return zone
end

-- True if the zone has been built (for memory reports and tests).
function DB.IsBuilt(uiMap)
    return DB.zones[uiMap] ~= nil
end

local function lookup(section, id)
    local index = DB.index
    local uiMap = index and index[section] and index[section][id]
    if uiMap == nil then
        return nil
    end
    local zone = DB.Zone(uiMap)
    local rows = zone and zone[section]
    return rows and rows[id], uiMap
end

-- Quest record and the uiMapID of the zone file that holds it.
function DB.Quest(id)
    return lookup("quests", id)
end

function DB.Npc(id)
    return lookup("npcs", id)
end

function DB.Object(id)
    return lookup("objects", id)
end

-- Zones that registered data, sorted by uiMapID (0, the outside bucket, excluded).
function DB.ZoneIds()
    local ids = {}
    local seen = {}
    for uiMap in pairs(DB.builders) do
        seen[uiMap] = true
    end
    for uiMap in pairs(DB.zones) do
        seen[uiMap] = true
    end
    for uiMap in pairs(seen) do
        if uiMap ~= 0 then
            ids[#ids + 1] = uiMap
        end
    end
    table.sort(ids)
    return ids
end
